let CURRENT_LANG = (() => {
  try { return localStorage.getItem('mf-lang') === 'en' ? 'en' : 'pt'; } catch { return 'pt'; }
})();

function ui(key, vars = {}) {
  let value = (UI_TEXT[CURRENT_LANG] && UI_TEXT[CURRENT_LANG][key]) || UI_TEXT.pt[key] || key;
  Object.entries(vars).forEach(([k,v]) => value = value.replaceAll(`{{${k}}}`, String(v)));
  return value;
}

function splitLocation(value = '') {
  const parts = String(value).split('|').map(s => s.trim()).filter(Boolean);
  if (parts.length > 1) return { cidade: parts[0], uf: parts.slice(1).join(' | ') };
  return { cidade: value.trim(), uf: '' };
}

function localizeProject(raw, lang = CURRENT_LANG) {
  const locale = raw[lang] || raw.pt;
  const loc = splitLocation(locale.location || '');
  return {
    ...raw,
    locale,
    title: locale.title,
    cat: raw.category[lang] || raw.category.pt,
    status: locale.status,
    statusOriginal: locale.status,
    cidade: loc.cidade,
    uf: loc.uf,
    ano: locale.year,
    area: locale.area,
    programa: locale.subtitle || null,
    equipe: locale.team || null,
    intro: locale.subtitle || locale.title,
    texto: locale.description || [],
    photographer: locale.photography || null,
    landscaping: locale.landscaping || null,
    engineering: locale.engineering || null,
    renderCredit: locale.render || null,
    imageAlts: {}
  };
}

let PROJECTS = PROJECTS_SOURCE.map(p => localizeProject(p));
function setSiteLanguage(lang) {
  CURRENT_LANG = lang === 'en' ? 'en' : 'pt';
  try { localStorage.setItem('mf-lang', CURRENT_LANG); } catch {}
  PROJECTS.splice(0, PROJECTS.length, ...PROJECTS_SOURCE.map(p => localizeProject(p)));
  document.documentElement.lang = CURRENT_LANG === 'en' ? 'en' : 'pt-BR';
}

